// Import of required libraries
import { test, expect, getBaseUrl, newSkyrampPlaywrightPage } from '@skyramp/skyramp';
import { addProductToCart, fillCheckoutEmail, fillShippingAddressStreet, placeOrder } from './skyrampUtils';

const pageTimeout = 15000;

// URL for test requests
const baseUrl = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:8080");

test.use({
    viewport: { width: 1280, height: 900 },
});

test('testUi', async ({ page }) => {
    test.setTimeout(89000);

    // set default timeout for all locator/page actions in this test
    page.setDefaultTimeout(pageTimeout);
    // Wrap playwright page with Skyramp page
    page = newSkyrampPlaywrightPage(page);

    await page.goto(`${baseUrl}/`);
    await page.goto(`${baseUrl}/product/OLJCESPC7Z`);
    await addProductToCart(page);
    await fillCheckoutEmail(page, "order.qa@skyramp.dev");
    await fillShippingAddressStreet(page, "500 Test Plaza");
    await expect(page.locator("#email-preview-panel .preview-to")).toHaveText("order.qa@skyramp.dev");
    await expect(page.locator("#email-preview-panel .preview-address")).toHaveText("500 Test Plaza, Mountain View, CA, 94043, United States");
    await expect(page.locator("#email-preview-panel .preview-total")).toHaveText("$28.98");

    // The preview's Total is the amount the customer is told they will be charged.
    // Capture it before checkout so the confirmation can be compared against it.
    const previewedTotal = (await page.locator("#email-preview-panel .preview-total").innerText()).trim();

    await placeOrder(page);
    await expect(page.getByRole("heading", { name: "Your order is complete!" })).toBeVisible();
    await expect(page).toHaveURL(`${baseUrl}/cart/checkout`);
    await expect(page.locator('div.row:has(> div:text-is("Total Paid")) > .text-right')).toHaveText(previewedTotal);
    await expect(page.locator('div.row:has(> div:text-is("Total Paid")) > .text-right')).toHaveText("$28.98");
});
